ALTER TABLE "notifications" ADD CONSTRAINT "notifications_git" CHECK (COALESCE(("notifications"."kind" NOT LIKE 'git.%' AND "notifications"."git_conversion_id" IS NULL AND "notifications"."git_attempt" IS NULL AND "notifications"."git_failure" IS NULL AND "notifications"."git_connection_id" IS NULL AND "notifications"."git_expires_at" IS NULL)
        OR ("notifications"."kind" = 'git.conversion.completed' AND "notifications"."git_conversion_id" IS NOT NULL AND "notifications"."git_attempt" >= 0 AND "notifications"."git_failure" IS NULL AND "notifications"."git_connection_id" IS NULL AND "notifications"."git_expires_at" IS NULL)
        OR ("notifications"."kind" = 'git.conversion.failed' AND "notifications"."git_conversion_id" IS NOT NULL AND "notifications"."git_attempt" >= 0 AND "notifications"."git_failure" ~ '^[a-z0-9_]{1,64}$' AND "notifications"."git_connection_id" IS NULL AND "notifications"."git_expires_at" IS NULL)
        OR ("notifications"."kind" = 'git.connection.token_expiring' AND "notifications"."git_connection_id" IS NOT NULL AND "notifications"."git_expires_at" IS NOT NULL AND "notifications"."git_conversion_id" IS NULL AND "notifications"."git_attempt" IS NULL AND "notifications"."git_failure" IS NULL), false));--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_kind" CHECK ("notifications"."kind" IN ('schedule.run.succeeded', 'schedule.run.failed', 'schedule.run.interrupted', 'schedule.run.skipped_actions', 'schedule.paused', 'skill.member_add.blocked', 'skill.deprecated', 'skill.version.deprecated', 'skill.version.withdrawn', 'skill.version.revoked', 'skill.version.unrevoked', 'skill.version.site_published', 'team.member.added', 'team.site_admin.member_added', 'team.site_admin.member_role_changed', 'team.site_admin.member_removed', 'team.site_admin.member_taken_over', 'memory.scope.near_full', 'memory.review.reminder', 'memory.review.digest', 'memory.review.candidates_ready', 'memory.proposal.received', 'memory.proposal.accepted', 'memory.proposal.dismissed', 'memory.proposal.changes_requested', 'memory.proposal.expired', 'memory.suggestion.received', 'memory.suggestion.accepted', 'memory.suggestion.dismissed', 'memory.suggestion.expired', 'memory.suggestion.stale', 'memory.site_proposal.received', 'memory.site_proposal.confirmed', 'memory.site_proposal.changes_requested', 'memory.site_proposal.accepted', 'memory.site_proposal.dismissed', 'memory.site_proposal.expired', 'git.conversion.completed', 'git.conversion.failed', 'git.connection.token_expiring'));--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_shape" CHECK (("notifications"."kind" = 'schedule.paused' AND "notifications"."thread_id" IS NULL AND "notifications"."run_id" IS NULL AND "notifications"."paused_by" IS NOT NULL AND "notifications"."skill_id" IS NULL AND "notifications"."skill_semver" IS NULL)
        OR ("notifications"."kind" LIKE 'team.%' AND "notifications"."schedule_id" IS NULL AND "notifications"."thread_id" IS NULL AND "notifications"."run_id" IS NULL AND "notifications"."paused_by" IS NULL AND "notifications"."skill_id" IS NULL AND "notifications"."skill_semver" IS NULL)
        OR ("notifications"."kind" LIKE 'skill.%' AND "notifications"."schedule_id" IS NULL AND "notifications"."thread_id" IS NULL AND "notifications"."run_id" IS NULL AND "notifications"."paused_by" IS NULL AND "notifications"."skill_id" IS NOT NULL
          AND ("notifications"."skill_semver" IS NOT NULL) = ("notifications"."kind" LIKE 'skill.version.%'))
        OR ("notifications"."kind" LIKE 'memory.%' AND "notifications"."schedule_id" IS NULL AND ("notifications"."thread_id" IS NULL OR "notifications"."kind" = 'memory.review.candidates_ready') AND "notifications"."run_id" IS NULL AND "notifications"."paused_by" IS NULL AND "notifications"."skill_id" IS NULL AND "notifications"."skill_semver" IS NULL)
        OR ("notifications"."kind" LIKE 'git.%' AND "notifications"."schedule_id" IS NULL AND "notifications"."thread_id" IS NULL AND "notifications"."run_id" IS NULL AND "notifications"."paused_by" IS NULL AND "notifications"."skill_id" IS NULL AND "notifications"."skill_semver" IS NULL)
        OR ("notifications"."kind" <> 'schedule.paused' AND "notifications"."kind" NOT LIKE 'skill.%' AND "notifications"."kind" NOT LIKE 'team.%' AND "notifications"."kind" NOT LIKE 'memory.%' AND "notifications"."kind" NOT LIKE 'git.%' AND "notifications"."thread_id" IS NOT NULL AND "notifications"."run_id" IS NOT NULL AND "notifications"."paused_by" IS NULL AND "notifications"."skill_id" IS NULL AND "notifications"."skill_semver" IS NULL));